def solve(values, qmax):
    import math
    if type(qmax) is not int or qmax<1 or any(not math.isfinite(v) for v in values): raise ValueError('quantizer')
    peak=max(map(abs,values),default=0)
    scale=peak/qmax if peak else 1
    codes=[max(-qmax,min(qmax,round(v/scale))) for v in values]
    return dict(scale=scale,codes=codes,reconstructed=[v*scale for v in codes])

